// The Supacharge wordmark as the Dart app draws it: the app name in
// Montserrat Black Italic with the registered mark AppHelpers appends
// (AppStyle.logoFontBlackItalic; the welcome, login and profile headers).
// The Dart app has no image wordmark - assets/images/logo.png is the
// kernel's Juvo mark - so these are the same glyphs traced from Montserrat
// Black Italic into one path, filled with currentColor so it takes the
// colour of wherever it sits. The same vector is installed as
// public/brand/supacharge-wordmark.svg (white) and
// supacharge-wordmark-ink.svg (light) for places that need a file.
//
// `title` is the glyphs' accessible name - what a screen reader says for
// the brand line in the footer, the one place the shell draws this
// vector as chrome. Since 1.21.0 it is the brand string "supacharge.school"
// (Ray, 2026-09-10, lowercase wherever it is written as the brand); the
// traced glyphs themselves are the app's wordmark and are not retraced.

import React from "react";

export const LMS_WORDMARK_VIEWBOX = "0 0 690 124";

/** Height in px; the width follows the glyphs (690:124). */
export function LmsWordmark({
  height = 32,
  className,
  title = "supacharge.school",
}: {
  height?: number;
  className?: string;
  title?: string;
}) {
  const width = Math.round((height * 690) / 124);
  return (
    <svg
      viewBox={LMS_WORDMARK_VIEWBOX}
      width={width}
      height={height}
      role="img"
      aria-label={title}
      className={className}
      fill="currentColor"
    >
      <path d={LMS_WORDMARK_PATH} />
    </svg>
  );
}

